import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionMme(EpcSectionGeneric):
    """
    Section "Mme" is a part of epc.lua config file.
    Generated content base on epc.yaml.
    Example generated for CLOUD_R4A_CUS:

    exec("set_mme id=1 ip=:10000 s1=10.0.1.1:36412 mmegi=1 mmec=3 supported_plmn=244:08 supported_plmn=666:14 supported_plmn=555:12")
    """

    def _prepare_section_content(self, epc_config, *args, **kwargs):
        mme_keys = filter(self._filter_mme, sorted(epc_config.keys()))
        if not mme_keys:
            return
        logger.debug("Generating MME section")
        subsection = []
        for mme in mme_keys:
            mme_data = epc_config[mme]
            mme_num = re.match(r'mme(?P<mme_num>\d+)', mme).group('mme_num')
            s1_addr = self.get_S1_addr(mme_data)
            mmegi, mmec = mme_data['mmegi'], mme_data['mmec']

            mme_line = f"set_mme id={mme_num} ip=:{self.EDAEMON_PORT} s1={s1_addr}:36412 mmegi={mmegi} mmec={mmec}"
            if 'supported_plmn' in mme_data:
                for plmn in mme_data['supported_plmn']:
                    mme_line += f' supported_plmn={plmn.replace("-", ":")}'

            subsection.append(EpcLine(line=mme_line, exec=True, tab_count=0))

        self._section_content.append(subsection)

    @staticmethod
    def get_S1_addr(mme_data):
        mme_s1_addr = '10.254.221.1'  # TODO must chceck if needed
        if 's1_addr' in mme_data and mme_data['s1_addr'] != 'default':
            mme_s1_addr = mme_data['s1_addr']

        return mme_s1_addr

    @staticmethod
    def _filter_mme(s: str):
        return re.match(r'mme\d+', s) is not None
